import{z as i,x as p,o as E,c as d,q as r,j as A,D as e,d as l,s as n,S as s,b as o}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"LZ77 / LZ78","description":"","frontmatter":{"title":"LZ77 / LZ78","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lz77-lz78.md","filePath":"cs/lz77-lz78.md","lastUpdated":1791413859000}'),B={name:"cs/lz77-lz78.md"};function m(c,a,L,h,D,Z){const t=p("Mermaid");return E(),d("div",null,[a[2]||(a[2]=r('<h1 id="lz77-lz78" tabindex="-1">LZ77 / LZ78 <a class="header-anchor" href="#lz77-lz78" aria-label="Permalink to &quot;LZ77 / LZ78&quot;">​</a></h1><div class="epigraph"><p>用已见过的子串当字典指针，不显式估计 $p$；对遍历性信源，码长比率几乎必然趋向熵率。</p><footer>—— 据 Ziv and Lempel, 1977, 1978；Cover and Thomas 整理</footer></div><p>上一课<a href="/cs/arithmetic-coding">算术编码</a> 仍要模型 \\(p\\)。缺口是<strong>通用压缩</strong>：LZ77 滑动窗口指针，LZ78 显式建字典。实践中的 gzip / zlib / GIF 落在这一族。不重写区间。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>LZ77：输出 \\((距离, 长度, 下一字符)\\)，指向窗口内最长匹配。LZ78：逐步把未见短语插入字典，输出 \\((索引, 字符)\\)。二者都不先扫全文件估 \\(p\\)。Ziv–Lempel 定理：对平稳遍历源，每符号比特 \\(\\to\\) 熵率。有限窗、有限字典是工程截断，理论用渐近窗。</p><p>与 Huffman：LZ 捕获重复字符串，Huffman 捕获字母频率；可串联（Deflate = LZ77 + Huffman）。</p><h3 id="不是「字典越大越好」" tabindex="-1">不是「字典越大越好」 <a class="header-anchor" href="#不是「字典越大越好」" aria-label="Permalink to &quot;不是「字典越大越好」&quot;">​</a></h3><p>指针要花钱。窗 \\(W\\) 太大，距离字段变长，且远匹配对局部源未必值。自适应算术对字母源更贴 \\(H\\)；LZ 对自然语言重复更直接。</p><p><span class="marginnote">Ziv–Lempel 1977（LZ77）、1978（LZ78）。Welch 的 LZW 是 78 的变体。Cover–Thomas 第 13 章通用编码。Knuth 对最优匹配的实现讨论点名即可。</span></p><p><span class="marginnote">数字实例：编码 <code>aabaabaa</code> 走到第 7 位时，窗口里已有 <code>aabaab</code>，向前退 3 格、复制 2 个字符正好得到余下的 <code>aa</code>——发一个三元组 (3, 2, 结束) 就代替了重抄两个字面。匹配越长，一个指针省得越多；毫无重复时只剩「字面+空指针」，反而膨胀。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用短串 <code>aabaabaa</code> 演示 LZ77 指针。强调：译码端用同一规则重建窗口，无需另传字典（LZ78 的字典从输出重建）。对比 Kolmogorov：LZ 是具体可计算的压缩器，给 \\(K\\) 的上界，不是 \\(K\\)。</p>',12)),(E(),A(s,null,{default:e(()=>[n(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20WIN%5B%22%E5%B7%B2%E8%A7%81%E7%AA%97%E5%8F%A3%20%2F%20%E5%AD%97%E5%85%B8%22%5D%20--%3E%20PTR%5B%22%E6%8C%87%E9%92%88%E4%BB%A3%E6%9B%BF%E5%8E%9F%E6%96%87%22%5D%0A%20%20PTR%20--%3E%20RATE%5B%22%E6%AF%94%E7%8E%87%20%E2%86%92%20%E7%86%B5%E7%8E%87%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[l("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,"通用性：同一算法对一切遍历源渐近最优，不必知道 \\(p\\)。有限 \\(n\\) 无保证压过错误模型的算术。不可压缩串（高 \\(K\\)）上 LZ 会膨胀，符合熵 \\(\\approx\\) 字长。",-1)),(E(),A(s,null,{default:e(()=>[n(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E8%AF%BB%E5%85%A5%E5%BD%93%E5%89%8D%E4%BD%8D%E7%BD%AE%22%5D%20--%3E%20SRCH%5B%22LZ77%3A%20%E5%9C%A8%E6%BB%91%E5%8A%A8%E7%AA%97%E5%8F%A3%E5%86%85%E6%89%BE%E6%9C%80%E9%95%BF%E5%8C%B9%E9%85%8D%22%5D%0A%20%20SRCH%20--%3E%20OUT77%5B%22%E8%BE%93%E5%87%BA%20(%E8%B7%9D%E7%A6%BB%2C%20%E9%95%BF%E5%BA%A6%2C%20%E4%B8%8B%E4%B8%80%E5%AD%97%E7%AC%A6)%22%5D%0A%20%20OUT77%20--%3E%20RB77%5B%22%E8%AF%91%E7%A0%81%E7%AB%AF%E5%9B%9E%E9%80%80%E5%A4%8D%E5%88%B6%2C%20%E7%AA%97%E5%8F%A3%E8%87%AA%E5%8A%A8%E9%87%8D%E5%BB%BA%22%5D%0A%20%20IN%20--%3E%20DIC%5B%22LZ78%3A%20%E6%8A%8A%E6%9C%AA%E8%A7%81%E7%9F%AD%E8%AF%AD%E9%80%90%E6%9D%A1%E6%8F%92%E5%85%A5%E5%AD%97%E5%85%B8%22%5D%0A%20%20DIC%20--%3E%20OUT78%5B%22%E8%BE%93%E5%87%BA%20(%E5%AD%97%E5%85%B8%E7%B4%A2%E5%BC%95%2C%20%E4%B8%8B%E4%B8%80%E5%AD%97%E7%AC%A6)%22%5D%0A%20%20OUT78%20--%3E%20RB78%5B%22%E8%AF%91%E7%A0%81%E7%AB%AF%E6%8C%89%E5%90%8C%E8%A7%84%E5%88%99%E9%95%BF%E5%87%BA%E5%90%8C%E4%B8%80%E6%A3%B5%E7%9F%AD%E8%AF%AD%E6%A0%91%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p><span class="marginnote">术语翻译：「字典可从码流重建」就是压缩端不另发字典文件——译码端看到的每条输出，恰好是编码端当年插入词典的那条，照同样规则长出的树必然一模一样。这是 LZ 族「自同步的字典」设计，也是下面错一位就全毁的原因。</span></p><p>信道编码不在本课：LZ 不抗噪声，指针错一位可以毁掉窗口同步。</p><p>LZW（Welch）把 LZ78 的「字符」改成只发索引，字典预装字母表，GIF/早年 Unix compress 用它。窗实现可用哈希找匹配，Knuth 讨论最优解析不必贪心最长，实践贪心足够。膨胀：对不可压缩数据指针开销大于字面，压缩器通常有「存原文」开关。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Deflate 比特格式，不比较 bzip2 / PAQ。不把 LZ 当字符串算法课的 KMP 替代。后课默认：无显式 \\(p\\) 的渐近最优用 LZ 族。下一课换问题：噪声信道容量。</p><p>通用性是渐近定理：有限窗对有限文件无最优保证。与算术串联（先 LZ 再 Huffman）是 Deflate 的形状。指针错位会毁掉窗口，故 LZ 不是信道码。</p><p><span class="marginnote">常见误区：初学者容易以为窗口开到整个文件，压缩率一定最高。实际上距离字段随窗口指数变长，远处的匹配对局部性强的数据也常不值那份指针钱；常见折中是几十 KB 量级的窗口。直觉类比：窗口像多米诺骨牌——译码一字不差地重建历史，错一位则后面全塌，所以 LZ 不抗噪声。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LZ77 窗口指针，LZ78 显式短语表；字典可从码流重建。</li><li>对遍历源渐近达到熵率：通用压缩。</li><li>给 \\(K\\) 上界，不是 \\(K\\) 本身。</li><li>出处：Ziv and Lempel, 1977/1978；Cover and Thomas。</li></ul>',9))])}const C=i(B,[["render",m]]);export{u as __pageData,C as default};
